<script setup>import { useNotificationStore } from '../../stores/notificationStore.js'; const store=useNotificationStore()</script>
<template><Teleport to="body"><div class="toast-stack" aria-live="polite"><TransitionGroup name="toast"><div v-for="toast in store.toasts" :key="toast.id" class="toast" :class="toast.type"><span class="toast-icon">{{ toast.type==='success'?'✓':toast.type==='error'?'!':'i' }}</span><span>{{ toast.message }}</span><button v-if="toast.action" @click="toast.action();store.remove(toast.id)">{{ toast.actionLabel }}</button><button class="toast-close" aria-label="Dismiss" @click="store.remove(toast.id)">×</button></div></TransitionGroup></div></Teleport></template>
